package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="buses") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class Bus { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,length=30) String registrationNumber; @Column(length=50) String model; @Column Integer capacity; @Column(length=20) String status; }
